  questions: [
    {
      id: "note-genetics-001",
      text: "Five alleles occur at one autosomal locus in a diploid population. How many different unordered heterozygous genotypes, excluding homozygotes, are possible?",
      options: [{ key: "a", text: "5" }, { key: "b", text: "10" }, { key: "c", text: "15" }, { key: "d", text: "25" }],
      answer: "b",
      explanation: "Choose two different alleles without counting their order: $\\frac{5\\times4}{2}=10$ heterozygous genotypes. Adding the five homozygotes would give fifteen total genotypes, but those are explicitly excluded.",
      sectionId: "gametes-probability", source: { document: "biology", page: 209 }, cognitive: "application"
    },
    {
      id: "note-genetics-002",
      text: "Clonal plants with the same allele constitution grow to different heights in two climates. Which conclusion follows without assuming a mutation?",
      options: [{ key: "a", text: "Their inherited alleles must have become different." }, { key: "b", text: "Their growth proves that every height allele is recessive." }, { key: "c", text: "Their original genotype must have blended permanently." }, { key: "d", text: "Their environment can change phenotype without changing genotype." }],
      answer: "d",
      explanation: "Phenotype depends on genotype and environment. Different growth of genetically identical plants can be environmental plasticity; it is not evidence by itself for a changed allele sequence or permanent blending.",
      sectionId: "gene-locus-phenotype", source: { document: "biology", page: 197 }, cognitive: "understanding"
    },
    {
      id: "note-genetics-003",
      text: "An Rr pea is selfed, with round R completely dominant and equal survival of all genotypes. A round F2 seed is selected at random. What is the probability that it is heterozygous?",
      options: [{ key: "a", text: "$\\frac{2}{3}$" }, { key: "b", text: "$\\frac{1}{2}$" }, { key: "c", text: "$\\frac{1}{4}$" }, { key: "d", text: "$\\frac{3}{4}$" }],
      answer: "a",
      explanation: "Rr selfing gives one RR, two Rr and one rr combination. Selection is restricted to round seeds, so the rr class is excluded. Of the three remaining combinations, two are Rr: $P(Rr\\mid\\text{round})=\\frac{2}{3}$.",
      sectionId: "mendel-segregation", source: { document: "biology", page: 209 }, cognitive: "application"
    },
    {
      id: "note-genetics-004",
      text: "Two round-seeded pea plants might be RR or Rr. Which breeding comparison most directly tests their genotypes under complete dominance?",
      options: [{ key: "a", text: "Cross each with a homozygous round-seeded RR plant." }, { key: "b", text: "Compare only the colours of their existing seeds." }, { key: "c", text: "Cross each with a homozygous wrinkled-seeded rr plant." }, { key: "d", text: "Interchange which round plant supplies pollen." }],
      answer: "c",
      explanation: "The rr tester supplies only r, so a wrinkled rr offspring reveals an r contribution from the tested parent. RR by rr gives all Rr; Rr by rr has a 1:1 expectation. A finite all-round sample still does not prove RR with certainty.",
      sectionId: "cross-types", source: { document: "biology", page: 197 }, cognitive: "application"
    },
    {
      id: "note-genetics-005",
      text: "AaBb plants are selfed at two independent loci with equal genotype survival. Among 144 expected offspring, how many should be homozygous at both loci, allowing either allele at each locus?",
      options: [{ key: "a", text: "36" }, { key: "b", text: "9" }, { key: "c", text: "72" }, { key: "d", text: "81" }],
      answer: "a",
      explanation: "At one selfed heterozygous locus, AA plus aa accounts for one half. Being homozygous at both independent loci has probability $\\frac{1}{2}\\times\\frac{1}{2}=\\frac{1}{4}$. The expected count is $144\\times\\frac{1}{4}=36$, not just the aabb class.",
      sectionId: "independent-assortment", source: { document: "biology", page: 196 }, cognitive: "application"
    },
    {
      id: "note-genetics-006",
      text: "Pigment requires a functional A allele and a functional B allele at different loci. Colourless AAbb and aaBB plants produce coloured AaBb offspring. What explains this result?",
      options: [{ key: "a", text: "Both parental defects permanently blend into one allele." }, { key: "b", text: "Each parent supplies the functional step missing in the other." }, { key: "c", text: "The recessive alleles become dominant during fertilization." }, { key: "d", text: "Chromosome number doubles when the two parents are crossed." }],
      answer: "b",
      explanation: "The AAbb parent supplies A but lacks functional B; aaBB supplies B but lacks functional A. Their AaBb offspring has both required functions. This is complementary action at different loci, not allele blending or chromosome doubling.",
      sectionId: "nonallelic-polygenic", source: { document: "biology", page: 209 }, cognitive: "application"
    },
    {
      id: "note-genetics-007",
      text: "In an AaBb self-cross, two independent loci contribute equal additive effects without dominance. What fraction of offspring is expected in the two extreme dosage classes combined?",
      options: [{ key: "a", text: "$\\frac{1}{16}$" }, { key: "b", text: "$\\frac{1}{4}$" }, { key: "c", text: "$\\frac{3}{8}$" }, { key: "d", text: "$\\frac{1}{8}$" }],
      answer: "d",
      explanation: "The zero-through-four contributing-allele classes have frequencies 1:4:6:4:1. The two extremes are aabb and AABB, each one sixteenth. Adding them gives $\\frac{1+1}{16}=\\frac{1}{8}$; the six-sixteenths middle class is not an extreme.",
      sectionId: "nonallelic-polygenic", source: { document: "biology", page: 198 }, cognitive: "application"
    },
    {
      id: "note-genetics-008",
      text: "A roan animal has intermixed red and white hairs, whereas a flower heterozygote has an intermediate pink colour. Which distinction best describes the two classroom models?",
      options: [{ key: "a", text: "Both require permanent blending of the parental alleles." }, { key: "b", text: "Roan is incomplete dominance; pink is complete dominance." }, { key: "c", text: "Roan illustrates codominance; pink illustrates incomplete dominance." }, { key: "d", text: "Roan proves polyploidy; pink proves cytoplasmic inheritance." }],
      answer: "c",
      explanation: "Codominance retains distinguishable effects of both alleles, as separate red and white hairs. Incomplete dominance gives an intermediate heterozygote phenotype. Neither model requires the alleles themselves to fuse or change identity.",
      sectionId: "allelic-interactions", source: { document: "biology", page: 198 }, cognitive: "understanding"
    },
    {
      id: "note-genetics-009",
      text: "An HbAS individual produces both HbA and HbS but does not have the usual HbSS disease phenotype. Which interpretation avoids confusing molecular expression with clinical inheritance?",
      options: [{ key: "a", text: "The HbS allele is absent until both parents transmit it." }, { key: "b", text: "Molecular codominance can coexist with a largely recessive disease phenotype." }, { key: "c", text: "Clinical recessiveness requires complete absence of HbS protein." }, { key: "d", text: "Producing both haemoglobins means the individual must have HbSS disease." }],
      answer: "b",
      explanation: "Both haemoglobin variants are detectable in a heterozygote, demonstrating codominance at the molecular level. The clinical disease comparison uses a different phenotype, so a largely recessive disease pattern does not contradict production of both proteins.",
      sectionId: "allelic-interactions", source: { document: "biology", page: 198 }, cognitive: "understanding"
    },
    {
      id: "note-genetics-010",
      text: "One parent is I<sup>A</sup>i and the other I<sup>B</sup>i. In the simple ABO model, what is the probability that the first child is group O and the second child is group AB?",
      options: [{ key: "a", text: "$\\frac{1}{16}$" }, { key: "b", text: "$\\frac{1}{8}$" }, { key: "c", text: "$\\frac{1}{4}$" }, { key: "d", text: "$\\frac{1}{2}$" }],
      answer: "a",
      explanation: "Each birth can give I-A I-B, I-A i, I-B i or ii with probability one quarter. The stated order requires O first and AB second: $\\frac{1}{4}\\times\\frac{1}{4}=\\frac{1}{16}$. No factor of two is added because the reverse order is not requested.",
      sectionId: "abo-multiple-alleles", source: { document: "biology", page: 199 }, cognitive: "application"
    },
    {
      id: "note-genetics-011",
      text: "An informative test cross gives 425 offspring in each parental class and 75 in each recombinant class. Ignoring undetected multiple crossovers for this short interval, what map distance is estimated?",
      options: [{ key: "a", text: "3 cM" }, { key: "b", text: "7.5 cM" }, { key: "c", text: "15 cM" }, { key: "d", text: "30 cM" }],
      answer: "c",
      explanation: "The total is $425+425+75+75=1000$ and both recombinant classes must be counted, giving 150. Recombination percentage is $\\frac{150}{1000}\\times100=15\\%$, approximately 15 cM under the stated short-interval approximation.",
      sectionId: "linkage-mapping", source: { document: "biology", page: 200 }, cognitive: "application"
    },
    {
      id: "note-genetics-012",
      text: "A parent has linked alleles in coupling phase AB/ab, and no crossing over occurs between these loci. Which pair of gamete types is absent from this model?",
      options: [{ key: "a", text: "Parental haplotypes: AB and ab" }, { key: "b", text: "Dominant-B haplotypes: AB and aB" }, { key: "c", text: "Recessive-b haplotypes: Ab and ab" }, { key: "d", text: "Recombinant haplotypes: Ab and aB" }],
      answer: "d",
      explanation: "The parental haplotypes are AB and ab. Without crossing over in the interval they remain intact, so the recombinant haplotypes Ab and aB are absent. This describes complete linkage, not every possible linked-gene cross.",
      sectionId: "linkage-mapping", source: { document: "biology", page: 199 }, cognitive: "understanding"
    },
    {
      id: "note-genetics-013",
      text: "Two markers show approximately 50% recombination. Which conclusion is justified from that result alone?",
      options: [{ key: "a", text: "They behave as effectively unlinked, but their chromosome locations remain uncertain." }, { key: "b", text: "They must be exactly 50 physical base pairs apart on the same chromosome." }, { key: "c", text: "Every meiosis must exchange both chromatids between the two markers." }, { key: "d", text: "They must lie on different chromosomes, with no other possible arrangement." }],
      answer: "a",
      explanation: "Different chromosomes can give 50% recombinant marker combinations, but distant loci on one chromosome can approach the same observed fraction because of multiple crossovers. The observation alone therefore does not uniquely locate them.",
      sectionId: "linkage-mapping", source: { document: "biology", page: 200 }, cognitive: "understanding"
    },
    {
      id: "note-genetics-014",
      text: "Reciprocal maize crosses give different male-sterility outcomes that track the seed parent's cytoplasm. Which explanation most directly fits this observation?",
      options: [{ key: "a", text: "A complete-dominance rule acting identically in both reciprocal crosses" }, { key: "b", text: "A universal conversion of paternal recessive alleles into dominant ones" }, { key: "c", text: "Independent assortment proving that all seven pea loci are unlinked" }, { key: "d", text: "Organelle inheritance involving mitochondrial factors and possible nuclear modifiers" }],
      answer: "d",
      explanation: "Maize cytoplasmic male sterility is associated with mitochondrial factors and can be modified by nuclear restorer genes. Tracking the seed parent's cytoplasm therefore supports an organellar contribution rather than an identical reciprocal autosomal model.",
      sectionId: "gene-classes-regulation", source: { document: "biology", page: 196 }, cognitive: "application"
    },
    {
      id: "note-genetics-015",
      text: "A diagram calls a Y-specific allele recessive solely because its effect appears in a male. What is the most precise correction for a locus with no X counterpart?",
      options: [{ key: "a", text: "Its visible effect makes the single Y-specific allele dominant." }, { key: "b", text: "Hemizygosity makes an ordinary paired-allele dominance label inapplicable." }, { key: "c", text: "Its male-limited effect makes the single Y-specific allele recessive." }, { key: "d", text: "Its sex-chromosome location makes the Y-specific allele codominant." }],
      answer: "b",
      explanation: "A Y-specific locus lacking an X homologue is represented by one copy in an ordinary XY male. Dominance and recessiveness describe comparisons of alleles in a paired genotype, so expression alone cannot supply that classification here.",
      sectionId: "sex-linked-inheritance", source: { document: "biology", page: 200 }, cognitive: "understanding"
    },
    {
      id: "note-genetics-016",
      text: "A confirmed carrier of an X-linked recessive allele and an unaffected father have already had two unaffected sons. In the same fully penetrant model, what is the risk that their next son is affected?",
      options: [{ key: "a", text: "$\\frac{1}{8}$" }, { key: "b", text: "$\\frac{1}{4}$" }, { key: "c", text: "$\\frac{1}{2}$" }, { key: "d", text: "$\\frac{3}{4}$" }],
      answer: "c",
      explanation: "For a son, the father supplies Y and the carrier mother supplies either X with equal probability. Her affected X is still transmitted with probability one half. Previous births do not change this probability; the sex of the next child is already specified.",
      sectionId: "sex-linked-inheritance", source: { document: "biology", page: 212 }, cognitive: "application"
    },
    {
      id: "note-genetics-017",
      text: "An X-linked recessive affected father and a carrier mother have children under an equal-sex, fully penetrant model. What fraction of all children is expected to be unaffected heterozygous carriers?",
      options: [{ key: "a", text: "$\\frac{1}{2}$" }, { key: "b", text: "$\\frac{3}{4}$" }, { key: "c", text: "$\\frac{1}{8}$" }, { key: "d", text: "$\\frac{1}{4}$" }],
      answer: "d",
      explanation: "All daughters receive the affected paternal X, and half receive the mother's unaffected X, becoming heterozygotes. Thus unaffected carriers are $\\frac{1}{2}$ daughters times $\\frac{1}{2}$ appropriate maternal transmission, or one quarter of all children. Ordinary XY sons are not heterozygous carriers.",
      sectionId: "sex-linked-inheritance", source: { document: "biology", page: 210 }, cognitive: "application"
    },
    {
      id: "note-genetics-018",
      text: "A father has an X-linked recessive condition. His partner's genotype is unknown. Assuming normal chromosome transmission and no new mutation, what can be concluded about every daughter?",
      options: [{ key: "a", text: "She inherits the father's X carrying the relevant allele." }, { key: "b", text: "She must be an unaffected carrier regardless of her mother." }, { key: "c", text: "She must have two copies of the affected allele." }, { key: "d", text: "She inherits the father's Y carrying the relevant allele." }],
      answer: "a",
      explanation: "A father transmits his X to each daughter. Whether she is an unaffected heterozygote or has two affected alleles depends on her maternal X, which is unspecified. Inheriting an allele is a firmer conclusion here than assigning a disease phenotype.",
      sectionId: "sex-linked-inheritance", source: { document: "biology", page: 212 }, cognitive: "understanding"
    },
    {
      id: "note-genetics-019",
      text: "A species has 2n = 12. At metaphase I after normal premeiotic replication, how many bivalents and chromatids are present in one meiocyte?",
      options: [{ key: "a", text: "12 bivalents and 12 chromatids" }, { key: "b", text: "6 bivalents and 12 chromatids" }, { key: "c", text: "6 bivalents and 24 chromatids" }, { key: "d", text: "12 bivalents and 24 chromatids" }],
      answer: "c",
      explanation: "Twelve chromosomes form six homologous pairs, hence six bivalents. Each of the twelve chromosomes has two chromatids after S phase, giving twenty-four chromatids. Replication doubles chromatids and DNA, not the chromosome count at this stage.",
      sectionId: "dna-chromosome-counts", source: { document: "biology", page: 201 }, cognitive: "application"
    },
    {
      id: "note-genetics-020",
      text: "Homologues have separated into two meiotic daughter cells, but sister chromatids remain attached and no new S phase occurs. What is the chromosome/DNA state in each daughter?",
      options: [{ key: "a", text: "2n chromosomes and 4C DNA" }, { key: "b", text: "n chromosomes and 2C DNA" }, { key: "c", text: "n chromosomes and C DNA" }, { key: "d", text: "2n chromosomes and C DNA" }],
      answer: "b",
      explanation: "Meiosis I reduces the homologous complement from 2n to n. Each retained chromosome still has two chromatids, so DNA content is 2C rather than C. Interkinesis has no replication; meiosis II later partitions those chromatids.",
      sectionId: "dna-chromosome-counts", source: { document: "biology", page: 202 }, cognitive: "understanding"
    },
    {
      id: "note-genetics-021",
      text: "A mitotic cell has 2n = 16. After sister chromatids separate but before cytokinesis, how many daughter-chromosome centromeres are in the whole cell and at each pole?",
      options: [{ key: "a", text: "16 in the whole cell; 8 at each pole" }, { key: "b", text: "16 in the whole cell; 16 at each pole" }, { key: "c", text: "32 in the whole cell; 16 at each pole" }, { key: "d", text: "32 in the whole cell; 32 at each pole" }],
      answer: "c",
      explanation: "Each of sixteen replicated chromosomes yields two daughter chromosomes at anaphase. There are therefore thirty-two separated centromeres in the still-undivided cell and sixteen at each pole. This transient total is not chromosome-set doubling in each daughter nucleus.",
      sectionId: "dna-chromosome-counts", source: { document: "biology", page: 203 }, cognitive: "application"
    },
    {
      id: "note-genetics-022",
      text: "A meiocyte contains 16 pg of nuclear DNA after premeiotic S phase, corresponding to 4C. With normal divisions, how much nuclear DNA is in each completed meiotic product before any new replication?",
      options: [{ key: "a", text: "2 pg" }, { key: "b", text: "4 pg" }, { key: "c", text: "8 pg" }, { key: "d", text: "16 pg" }],
      answer: "b",
      explanation: "If 4C is 16 pg, then $C=\\frac{16}{4}=4$ pg. Each final product after meiosis II contains n chromosomes and C DNA. Meiosis I daughters would contain 2C, or 8 pg, but they are not the completed products asked for.",
      sectionId: "dna-chromosome-counts", source: { document: "biology", page: 202 }, cognitive: "application"
    },
    {
      id: "note-genetics-023",
      text: "Two sister chromatids at telophase I carry different marker combinations, although no new mutation occurred. Which preceding event can explain the difference?",
      options: [{ key: "a", text: "Exchange involving a nonsister chromatid during prophase I" }, { key: "b", text: "A second S phase between the two meiotic divisions" }, { key: "c", text: "Translation of a chromosome into a new polypeptide" }, { key: "d", text: "Fusion of both homologues into one permanent chromosome" }],
      answer: "a",
      explanation: "A crossover can exchange a segment between one chromatid and a nonsister chromatid of the other homologue. The two original sisters can therefore differ at linked markers by telophase I, without a mutation or a second DNA replication.",
      sectionId: "meiosis-one-stages", source: { document: "biology", page: 201 }, cognitive: "understanding"
    },
    {
      id: "note-genetics-024",
      text: "A chart groups mature human RBCs with reversible G0 cells that can return to S phase. What is the decisive problem with that grouping?",
      options: [{ key: "a", text: "Mature RBCs are continuously carrying out nuclear meiosis." }, { key: "b", text: "Mature RBCs contain twice as much nuclear DNA as neurons." }, { key: "c", text: "Mature RBCs divide only after their chromosomes pair." }, { key: "d", text: "Mature RBCs lack a nucleus and cannot resume nuclear DNA replication." }],
      answer: "d",
      explanation: "Mature human red cells are anucleate. They cannot behave as a quiescent nucleated cell re-entering G1 and S. Reversible quiescence must also be distinguished from terminal differentiation in other cell types.",
      sectionId: "interphase-cell-cycle", source: { document: "biology", page: 203 }, cognitive: "understanding"
    },
    {
      id: "note-genetics-025",
      text: "A diploid cell completes S phase normally but has not entered mitosis. Which comparison with its earlier G1 state is correct?",
      options: [{ key: "a", text: "Chromosome number doubles while DNA amount stays unchanged." }, { key: "b", text: "DNA amount doubles while the centromere-based chromosome count stays unchanged." }, { key: "c", text: "Both chromosome count and DNA amount are reduced by half." }, { key: "d", text: "DNA amount stays unchanged while every chromosome loses one chromatid." }],
      answer: "b",
      explanation: "Replication changes each chromosome from one chromatid to two sisters. DNA goes from 2C to 4C, but there are still 2n centromere-defined chromosomes before sister separation. Counting the four arms of an X-shaped drawing as chromosomes would be incorrect.",
      sectionId: "interphase-cell-cycle", source: { document: "biology", page: 203 }, cognitive: "understanding"
    },
    {
      id: "note-genetics-026",
      text: "In a dividing plant cell, Golgi vesicles fuse at the equator. A label calls each vesicle a phragmoplast. What should the label distinguish?",
      options: [{ key: "a", text: "The phragmoplast is an individual chromosome, not the guiding array." }, { key: "b", text: "The phragmoplast is a contractile animal ring, not a plant structure." }, { key: "c", text: "The phragmoplast guides the vesicles, which fuse to build the cell plate." }, { key: "d", text: "The phragmoplast is the nucleolus, which becomes the cell plate." }],
      answer: "c",
      explanation: "The phragmoplast is a cytoskeletal assembly that directs vesicles toward the division plane. The vesicles contribute membrane and wall materials to the growing cell plate; a vesicle and the guiding structure are not the same object.",
      sectionId: "mitotic-stages-cytokinesis", source: { document: "biology", page: 203 }, cognitive: "understanding"
    },
    {
      id: "note-genetics-027",
      text: "Which protein system primarily forms the contractile ring responsible for ordinary animal-cell cleavage-furrow constriction?",
      options: [{ key: "a", text: "Histone and DNA" }, { key: "b", text: "Tubulin and primase" }, { key: "c", text: "Keratin and ligase" }, { key: "d", text: "Actin and myosin" }],
      answer: "d",
      explanation: "The cytokinetic contractile ring uses actin filaments and myosin motors beneath the plasma membrane. Spindle microtubules help organize chromosome segregation and division positioning but are not the contractile ring itself.",
      sectionId: "mitotic-stages-cytokinesis", source: { document: "biology", page: 203 }, cognitive: "recall"
    },
    {
      id: "note-genetics-028",
      text: "A plant lineage normally has 20 chromosomes per diploid cell. After spindle interference, a recovered cell retains a doubled complete complement. Which count and classification fit this outcome?",
      options: [{ key: "a", text: "40 chromosomes; whole-set polyploidy" }, { key: "b", text: "21 chromosomes; whole-set polyploidy" }, { key: "c", text: "40 chromosomes; monosomy of one chromosome" }, { key: "d", text: "19 chromosomes; tetrasomy of one chromosome" }],
      answer: "a",
      explanation: "Doubling the complete diploid complement gives $2\\times20=40$ chromosomes, a tetraploid complement in this diploid starting model. Adding or losing one particular chromosome would instead give an aneuploid count such as 21 or 19.",
      sectionId: "mitotic-stages-cytokinesis", source: { document: "biology", page: 203 }, cognitive: "application"
    },
    {
      id: "note-genetics-029",
      text: "Which term describes a chromosome inversion confined to one arm and excluding the centromere?",
      options: [{ key: "a", text: "Pericentric inversion" }, { key: "b", text: "Reciprocal translocation" }, { key: "c", text: "Tandem duplication" }, { key: "d", text: "Paracentric inversion" }],
      answer: "d",
      explanation: "A paracentric inversion reverses a segment without including the centromere. A pericentric inversion spans the centromere. A translocation changes the segment's location and a duplication adds a copy rather than merely reversing its orientation.",
      sectionId: "chromosomal-structure", source: { document: "biology", page: 206 }, cognitive: "recall"
    },
    {
      id: "note-genetics-030",
      text: "A species normally has 2n = 18, but a cell has only 16 chromosomes. Can total count alone distinguish nullisomy from double monosomy?",
      options: [{ key: "a", text: "Yes; sixteen establishes loss of both homologues of one pair." }, { key: "b", text: "No; identifying which chromosomes are absent distinguishes them." }, { key: "c", text: "Yes; sixteen establishes one loss from each of two pairs." }, { key: "d", text: "No; nullisomy and double monosomy name an identical condition." }],
      answer: "b",
      explanation: "Nullisomy removes both homologues of one pair: $18-2=16$. Double monosomy removes one chromosome from each of two pairs: $18-1-1=16$. Their totals coincide, so identifying the absent chromosome types is essential.",
      sectionId: "aneuploidy-syndromes", source: { document: "biology", page: 205 }, cognitive: "application"
    },
    {
      id: "note-genetics-031",
      text: "Bread wheat has 42 chromosomes in a somatic cell and basic chromosome number x = 7. Which combination correctly states its ploidy and its normal gametic chromosome number?",
      options: [{ key: "a", text: "Triploid; 7 chromosomes per gamete" }, { key: "b", text: "Tetraploid; 14 chromosomes per gamete" }, { key: "c", text: "Hexaploid; 21 chromosomes per gamete" }, { key: "d", text: "Octoploid; 28 chromosomes per gamete" }],
      answer: "c",
      explanation: "The basic-set count is $\\frac{42}{7}=6$, so the plant is hexaploid. Normal reduction gives $\\frac{42}{2}=21$ chromosomes per gamete. The basic number x = 7 is therefore not the same as its gametic number n = 21.",
      sectionId: "polyploidy-examples", source: { document: "biology", page: 206 }, cognitive: "application"
    },
    {
      id: "note-genetics-032",
      text: "Two different diploid plant species each have 18 chromosomes. Their haploid gametes form a poorly fertile hybrid. If chromosome-set doubling restores pairing partners, what chromosome count is expected in the doubled hybrid?",
      options: [{ key: "a", text: "36" }, { key: "b", text: "18" }, { key: "c", text: "27" }, { key: "d", text: "72" }],
      answer: "a",
      explanation: "Each gamete contains nine chromosomes, so the initial hybrid has $9+9=18$. Doubling gives $2\\times18=36$, providing a homologous partner for each parental chromosome. The fertility explanation is improved pairing, not an extra gamete fusion.",
      sectionId: "polyploidy-examples", source: { document: "biology", page: 206 }, cognitive: "application"
    },
    {
      id: "note-genetics-033",
      text: "A DNA substitution replaces cytosine with thymine. How is this change classified by base-ring class?",
      options: [{ key: "a", text: "Purine-to-pyrimidine transversion" }, { key: "b", text: "Pyrimidine-to-purine transversion" }, { key: "c", text: "Pyrimidine-to-pyrimidine transition" }, { key: "d", text: "Purine-to-purine transition" }],
      answer: "c",
      explanation: "Cytosine and thymine are both single-ring pyrimidines. Replacing one with the other is a transition. A transversion instead crosses between purine and pyrimidine classes and does not describe this substitution.",
      sectionId: "point-mutation-types", source: { document: "biology", page: 205 }, cognitive: "recall"
    },
    {
      id: "note-genetics-034",
      text: "Six nucleotides encoding two sense codons are inserted precisely between codons within a coding sequence. No other change occurs. What follows for the downstream reading frame?",
      options: [{ key: "a", text: "It is preserved, although two added amino acids may affect function." }, { key: "b", text: "It shifts by one nucleotide and changes all upstream codons." }, { key: "c", text: "It shifts by two nucleotides and deletes the original chromosome." }, { key: "d", text: "It is preserved, which guarantees that protein function is unchanged." }],
      answer: "a",
      explanation: "Six is divisible by three, so inserting two complete sense codons at a codon boundary preserves subsequent triplet grouping. Two amino acids are added. Frame preservation does not guarantee unchanged folding or function, and upstream codons are not rewritten.",
      sectionId: "point-mutation-types", source: { document: "biology", page: 205 }, cognitive: "application"
    },
    {
      id: "note-genetics-035",
      text: "Which named source reagent is an intercalating dye associated with insertion/deletion errors and frameshift mutagenesis?",
      options: [{ key: "a", text: "Colchicine" }, { key: "b", text: "Hydroxylamine" }, { key: "c", text: "Folic acid" }, { key: "d", text: "Proflavine" }],
      answer: "d",
      explanation: "Proflavine is an acridine-family intercalating dye associated with frameshift-generating insertion/deletion errors. Colchicine primarily interferes with microtubules, hydroxylamine modifies bases, and folate supports normal nucleotide metabolism.",
      sectionId: "mutation-causes", source: { document: "biology", page: 205 }, cognitive: "recall"
    },
    {
      id: "note-genetics-036",
      text: "The beta-globin coding-DNA triplet GAG changes to GTG in the classic HbS variant. Which description correctly combines the DNA change and its coding effect?",
      options: [{ key: "a", text: "A transition producing a frameshift" }, { key: "b", text: "A transversion producing a missense change" }, { key: "c", text: "A three-base deletion producing a stop codon" }, { key: "d", text: "A chromosome inversion producing a duplicated gene" }],
      answer: "b",
      explanation: "The middle base changes A to T, a purine-to-pyrimidine transversion. The mRNA changes GAG to GUG, replacing glutamate with valine. The triplet length is unchanged, so this is missense substitution rather than a frameshift.",
      sectionId: "point-mutation-types", source: { document: "biology", page: 205 }, cognitive: "application"
    },
    {
      id: "note-genetics-037",
      text: "A microorganism reverses UV-induced pyrimidine dimers using photolyase and visible light. Does that observation establish the same repair pathway in human skin cells?",
      options: [{ key: "a", text: "No; humans lack functional photolyase-mediated photoreactivation." }, { key: "b", text: "Yes; every cellular DNA-repair pathway is identical in every species." }, { key: "c", text: "Yes; any exposure to visible light reverses every DNA mutation." }, { key: "d", text: "No; humans have no mechanism for repairing UV-associated DNA damage." }],
      answer: "a",
      explanation: "Photoreactivation is organism-dependent. Humans do not have functional photolyase-mediated photoreactivation, but do have other DNA-repair mechanisms, including nucleotide-excision repair. Neither universal pathway identity nor absence of all repair follows.",
      sectionId: "photo212-molecular-audit", source: { document: "biology", page: 212 }, cognitive: "understanding"
    },
    {
      id: "note-genetics-038",
      text: "Across both strands, a fully paired DNA fragment contains 300 adenines and 200 cytosines. Using ordinary A-T and G-C pairing, how many hydrogen bonds join its base pairs?",
      options: [{ key: "a", text: "500" }, { key: "b", text: "1000" }, { key: "c", text: "1200" }, { key: "d", text: "1500" }],
      answer: "c",
      explanation: "Each A identifies one A-T pair and each C one G-C pair in the complete duplex. There are 300 A-T pairs with two bonds each and 200 G-C pairs with three: $300\\times2+200\\times3=1200$ hydrogen bonds. Five hundred is the base-pair count, not the bond count.",
      sectionId: "dna-architecture", source: { document: "biology", page: 207 }, cognitive: "application"
    },
    {
      id: "note-genetics-039",
      text: "A primary transcript is 1000 nucleotides long. Splicing removes 300, and the mature transcript retains 100 untranslated nucleotides. If the remaining coding region contains exactly one terminal stop codon, how many amino acids are encoded?",
      options: [{ key: "a", text: "200" }, { key: "b", text: "199" }, { key: "c", text: "233" }, { key: "d", text: "299" }],
      answer: "b",
      explanation: "Coding length is $1000-300-100=600$ nucleotides, or $\\frac{600}{3}=200$ codons. One is a terminal stop that contributes no amino acid, leaving $200-1=199$. Introns and retained untranslated regions must both be excluded before counting coding triplets.",
      sectionId: "genetic-code-processing", source: { document: "biology", page: 212 }, cognitive: "application"
    },
    {
      id: "note-genetics-040",
      text: "Four ribosomes simultaneously traverse one mRNA and each produces the same polypeptide. What does this arrangement most directly increase?",
      options: [{ key: "a", text: "The number of different alleles at the DNA locus" }, { key: "b", text: "The number of chromosome sets in the cell" }, { key: "c", text: "The number of distinct genetic codes used by the cell" }, { key: "d", text: "The number of polypeptide copies made from one transcript" }],
      answer: "d",
      explanation: "This is a polysome: multiple ribosomes translate the same mRNA. It increases protein output per transcript without requiring new gene copies, additional chromosome sets or different codon assignments at the different ribosomes.",
      sectionId: "rna-types-polysomes", source: { document: "biology", page: 207 }, cognitive: "understanding"
    },
    {
      id: "note-genetics-041",
      text: "A molecular sketch shows a modified 5' guanosine cap and a 3' poly(A) tail. Which structure does this most typically represent?",
      options: [{ key: "a", text: "An ordinary bacterial DNA replication origin" }, { key: "b", text: "A processed eukaryotic messenger RNA" }, { key: "c", text: "A complete double-stranded chromosome" }, { key: "d", text: "A paired tRNA anticodon stem" }],
      answer: "b",
      explanation: "A 5' cap and, for most transcripts, a 3' poly(A) tail are characteristic processing features of eukaryotic mRNA. Their presence does not label leading and lagging DNA strands or establish a capped DNA-replication starting end.",
      sectionId: "genetic-code-processing", source: { document: "biology", page: 208 }, cognitive: "recall"
    },
    {
      id: "note-genetics-042",
      text: "In the usual bacterial decoding model, GUG is used once as an initiation signal and once internally within a coding sequence. Which amino-acid assignments fit these two contexts?",
      options: [{ key: "a", text: "Initiation: valine; internal position: formylmethionine" }, { key: "b", text: "Initiation: valine; internal position: valine" }, { key: "c", text: "Initiation: formylmethionine; internal position: tryptophan" }, { key: "d", text: "Initiation: formylmethionine; internal position: valine" }],
      answer: "d",
      explanation: "An alternative bacterial start GUG is recognized by initiator tRNA carrying formylmethionine. Internally, GUG specifies valine. The difference is defined by initiation context, not random failure of the genetic code to specify a result.",
      sectionId: "genetic-code-processing", source: { document: "quick-revision", page: 140 }, cognitive: "understanding"
    },
    {
      id: "note-genetics-043",
      text: "A bacterial replication preparation removes RNA primers and replaces them with DNA, but adjacent completed fragments retain unsealed backbone nicks. Which activity is most directly missing?",
      options: [{ key: "a", text: "DNA ligase activity" }, { key: "b", text: "Helicase activity" }, { key: "c", text: "Primase activity" }, { key: "d", text: "Ribosomal peptidyl-transfer activity" }],
      answer: "a",
      explanation: "Primer removal and DNA gap filling have already occurred. The remaining defect is sealing a nick between adjacent DNA ends, which requires ligase-mediated phosphodiester-bond formation. Helicase and primase act at different earlier steps.",
      sectionId: "replication-machinery", source: { document: "biology", page: 208 }, cognitive: "application"
    },
    {
      id: "note-genetics-044",
      text: "Both strands of one DNA duplex are permanently labelled. It undergoes three semiconservative replications using only unlabelled new material. What fraction of final duplexes retains an original labelled strand?",
      options: [{ key: "a", text: "$\\frac{1}{8}$" }, { key: "b", text: "$\\frac{1}{2}$" }, { key: "c", text: "$\\frac{1}{4}$" }, { key: "d", text: "$\\frac{3}{4}$" }],
      answer: "c",
      explanation: "Three rounds produce $2^3=8$ duplexes. There remain only two original labelled strands, each residing in one duplex paired with new DNA. Thus two of eight duplexes retain an original label: $\\frac{2}{8}=\\frac{1}{4}$.",
      sectionId: "replication-machinery", source: { document: "biology", page: 208 }, cognitive: "application"
    },
    {
      id: "note-genetics-045",
      text: "Helicase opens a DNA fork normally, but the exposed templates rapidly reanneal or form hairpins. Which missing component best explains this specific defect?",
      options: [{ key: "a", text: "DNA polymerase I (primer removal)" }, { key: "b", text: "DNA ligase (nick sealing)" }, { key: "c", text: "DNA gyrase (topology control)" }, { key: "d", text: "SSB (single-strand stabilization)" }],
      answer: "d",
      explanation: "SSB stabilizes exposed single-stranded templates and limits reannealing and inappropriate secondary structures. The stem states that duplex opening already works, so the problem is stabilization after opening rather than lack of helicase activity.",
      sectionId: "replication-machinery", source: { document: "quick-revision", page: 140 }, cognitive: "application"
    },
    {
      id: "note-genetics-046",
      text: "A student draws the lagging strand as newly synthesized 3' to 5' because it grows away from the fork. Which replacement correctly separates direction from continuity?",
      options: [{ key: "a", text: "Both strands are synthesized 3' to 5', but only one is continuous." }, { key: "b", text: "Only leading DNA needs a template; lagging DNA is assembled randomly." }, { key: "c", text: "Both strands are synthesized 5' to 3'; lagging DNA uses repeated fragments." }, { key: "d", text: "Lagging DNA is synthesized 3' to 5' until the RNA primer is removed." }],
      answer: "c",
      explanation: "DNA polymerases add to a free 3' hydroxyl, so each new segment grows 5' to 3'. Antiparallel template orientation relative to fork movement necessitates discontinuous lagging-strand synthesis but does not reverse the chemistry of chain extension.",
      sectionId: "replication-machinery", source: { document: "biology", page: 208 }, cognitive: "understanding"
    },
    {
      id: "note-genetics-047",
      text: "An RNA sample must first be converted into complementary DNA and then the DNA amplified. Which order of template-dependent activities is appropriate?",
      options: [{ key: "a", text: "DNA ligase, followed by RNA-dependent RNA polymerase" }, { key: "b", text: "Reverse transcriptase, followed by DNA-dependent DNA polymerase" }, { key: "c", text: "Primase, followed by a ribosomal peptidyl-transfer activity" }, { key: "d", text: "Restriction endonuclease, followed by terminal transferase" }],
      answer: "b",
      explanation: "Reverse transcriptase copies RNA into DNA. DNA-dependent DNA polymerase can then amplify the DNA template in PCR. Ligase joins ends, restriction enzymes cut sites, and terminal transferase adds bases without performing the required template-copying sequence.",
      sectionId: "molecular-tools", source: { document: "biology", page: 208 }, cognitive: "application"
    },
    {
      id: "note-genetics-048",
      text: "Which source-listed enzyme can add deoxynucleotides to a DNA 3' end without reading a complementary template?",
      options: [{ key: "a", text: "Terminal transferase" }, { key: "b", text: "DNA polymerase III" }, { key: "c", text: "RNA primase" }, { key: "d", text: "Restriction endonuclease" }],
      answer: "a",
      explanation: "Terminal deoxynucleotidyl transferase performs template-independent addition at a DNA 3' end. Ordinary replicative DNA polymerase reads a template, primase synthesizes RNA primers, and restriction endonuclease cleaves DNA rather than extending it.",
      sectionId: "molecular-tools", source: { document: "biology", page: 208 }, cognitive: "recall"
    },
    {
      id: "note-genetics-049",
      text: "Using the usual X-inactivation rule, how many Barr bodies are expected in typical somatic nuclei with 47,XXX and 47,XXY karyotypes, respectively?",
      options: [{ key: "a", text: "2 and 1" }, { key: "b", text: "3 and 2" }, { key: "c", text: "1 and 0" }, { key: "d", text: "2 and 0" }],
      answer: "a",
      explanation: "The usual count is the number of X chromosomes minus one. XXX has $3-1=2$ inactive-X bodies and XXY has $2-1=1$. The Y does not add a Barr body, and the XXY result shows why Barr bodies are not restricted to female-phenotype individuals.",
      sectionId: "photo211-genetic-models", source: { document: "biology", page: 211 }, cognitive: "application"
    },
    {
      id: "note-genetics-050",
      text: "A small founding group carries an allele at a different frequency from the large population it left. No survival or reproductive advantage is associated with the allele. Which explanation best fits the stated evidence?",
      options: [{ key: "a", text: "A necessary increase in the allele's selective advantage" }, { key: "b", text: "Random sampling of alleles when the founders were drawn" }, { key: "c", text: "Directed conversion of all alternative alleles into that allele" }, { key: "d", text: "A requirement that every founder undergo the same new mutation" }],
      answer: "b",
      explanation: "A small set of founders is a finite sample and need not match the original allele frequency exactly. This is a founder-associated genetic-drift explanation. The stem supplies no differential fitness or shared mutation that would justify the alternatives.",
      sectionId: "photo212-inheritance-audit", source: { document: "biology", page: 212 }, cognitive: "application"
    }
  ]
